{{ru-noun-table|old=1|дитя́|gen_sg=дитя́ти|dat_sg=дитя́ти|acc_sg=дитя́|ins_sg=дитя́темъ|pre_sg=дитя́ти|nom_pl=дитя́та|gen_pl=дитя́тъ|dat_pl=дитя́тамъ|acc_pl=дитя́тъ|ins_pl=дитя́тами|pre_pl=дитя́тахъ}}

